head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gIsurCd;
scwin.gProcType = "N"; // 디폴트는 신규모드
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.vData1 = "E";
scwin.vData2 = "E";
scwin.vData3 = "E";
scwin.vScrenID = 'ULDSTF26610.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParentValue = function() {
    scwin.gIsurCd = scwin.gIsurCd = $c.stf.getQuery(frame.srcUrl, "ISUR_CD");
    var gComNm = $c.stf.getQuery(frame.srcUrl, "COM_ABBRV");
    if ($c.ut.trim(scwin.gIsurCd).length == 5) {
        //alert(gIsurCd);
        $c.stf.setObjectValue(txb_ISUR_CD, scwin.gIsurCd);
        $c.stf.setObjectValue(txb_COM_NM, gComNm);
        scwin.gProcType = "M"; // 수정모드
        scwin.fn_InitSearch();
    }
};
scwin.fn_SetCode = function() {
    // 미제출사유  셋팅
    dts_nsubmitRsn1.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=REGUL_WRTRPT_NSUBMIT_RSN_CD";
    dts_nsubmitRsn1.Reset();
    dts_nsubmitRsn2.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=REGUL_WRTRPT_NSUBMIT_RSN_CD";
    dts_nsubmitRsn2.Reset();
    dts_nsubmitRsn3.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=REGUL_WRTRPT_NSUBMIT_RSN_CD";
    dts_nsubmitRsn3.Reset();
};


// 화면 로딩시 디폴트 검색
scwin.fn_InitSearch = function() {
    fn_Search();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !조건체크--;
사용자;
클릭-- > function() {
    // 법인코드 자리수 체크 
    if ($c.stf.getObjectValue(txb_ISUR_CD).length != 5) {
        $c.win.alert("회사코드 5자리를 올바르게 입력하십시오.");
        txb_ISUR_CD.focus();
        return;
    }
} < !조회--;
사용자;
클릭-- > function() {
    var url = "/SubmitStatus.do?method=readNSubmitInfo&inputMessageId=NSUBMIT_INFO_INOUT" + "&outputMessageId=NSUBMIT_INFO_INOUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //  데이타 조회
    dts_nsubmit_info.DataID = encodeURI(url);
    dts_nsubmit_info.reset();
};
scwin.fn_chkValueExist = function(obj1, obj2, obj3) {
    var vValCnt = 0;
    if ($c.stf.getObjectValue(obj1) == "") {
        vValCnt = vValCnt + 1;
    }
    if ($c.stf.getObjectValue(obj2) == "") {
        vValCnt = vValCnt + 3;
    }
    if ($c.stf.getObjectValue(obj3) == "") {
        vValCnt = vValCnt + 5;
    }
    return vValCnt;
};
scwin.fn_CheckValue = function() {
    var vIsurCd = $c.stf.getObjectValue(txb_isurcd);
    if (vIsurCd == "") {
        $c.win.alert("회사코드로  내역조회후에 입력처리가 가능합니다.");
        txb_ISUR_CD.focus();
        return false;
    }

    // 신규입력일때 
    if (scwin.gProcType == "N") {
        // 한개이상 데이터 입력 필요.
        if ($c.stf.getObjectValue(edt_design_dd1) == "" && $c.stf.getObjectValue(edt_end_dd1) == "" && $c.stf.getObjectValue(cmb_nsubmit_rsn1) == "" &&
            $c.stf.getObjectValue(edt_design_dd2) == "" && $c.stf.getObjectValue(edt_end_dd2) == "" && $c.stf.getObjectValue(cmb_nsubmit_rsn2) == "" &&
            $c.stf.getObjectValue(edt_design_dd3) == "" && $c.stf.getObjectValue(edt_end_dd3) == "" && $c.stf.getObjectValue(cmb_nsubmit_rsn3) == "") {
            $c.win.alert("한 건이상의 데이타를 입력하셔야 합니다.");
            edt_design_dd1.focus();
            return false;
        }
        var vValStat = scwin.fn_chkValueExist(edt_design_dd1, edt_end_dd1, cmb_nsubmit_rsn1);
        if (vValStat == 9) {
            $c.win.alert("한 건이상의 데이타를 입력하셔야 합니다.");
            edt_design_dd1.focus();
            return false;
        } else if (vValStat == 1 || vValStat == 4 || vValStat == 6) {
            $c.win.alert("지정일1을  입력하셔야 합니다.");
            edt_design_dd1.focus();
            return false;
        } else if (vValStat == 3 || vValStat == 8) {
            $c.win.alert("만료일1을  입력하셔야 합니다.");
            edt_end_dd1.focus();
            return false;
        } else if (vValStat == 5) {
            $c.win.alert("사유1을  입력하셔야 합니다.");
            cmb_nsubmit_rsn1.focus();
            return false;
        } else if (vValStat == 0) {
            scwin.vData1 = "I"; //

        }
        vValStat = scwin.fn_chkValueExist(edt_design_dd2, edt_end_dd2, cmb_nsubmit_rsn2);
        if (vValStat == 1 || vValStat == 4 || vValStat == 6) {
            $c.win.alert("지정일2를  입력하셔야 합니다.");
            edt_design_dd2.focus();
            return false;
        } else if (vValStat == 3 || vValStat == 8) {
            $c.win.alert("만료일2를  입력하셔야 합니다.");
            edt_end_dd2.focus();
            return false;
        } else if (vValStat == 5) {
            $c.win.alert("사유2를  입력하셔야 합니다.");
            cmb_nsubmit_rsn2.focus();
            return false;
        } else if (vValStat == 0) {
            scwin.vData2 = "I"; //

        }
        vValStat = scwin.fn_chkValueExist(edt_design_dd3, edt_end_dd3, cmb_nsubmit_rsn3);
        if (vValStat == 1 || vValStat == 4 || vValStat == 6) {
            $c.win.alert("지정일3을  입력하셔야 합니다.");
            edt_design_dd3.focus();
            return false;
        } else if (vValStat == 3 || vValStat == 8) {
            $c.win.alert("만료일3을  입력하셔야 합니다.");
            edt_end_dd3.focus();
            return false;
        } else if (vValStat == 5) {
            $c.win.alert("사유3을  입력하셔야 합니다.");
            cmb_nsubmit_rsn3.focus();
            return false;
        } else if (vValStat == 0) {
            scwin.vData3 = "I"; //

        }
    } else {
        // 첫번째
        if ($c.stf.getObjectValue(edt_design_dd1_old) == $c.stf.getObjectValue(edt_design_dd1) &&
            $c.stf.getObjectValue(edt_end_dd1_old) == $c.stf.getObjectValue(edt_end_dd1) &&
            $c.stf.getObjectValue(txt_nsubmit_rsn1_old) == $c.stf.getObjectValue(cmb_nsubmit_rsn1)) {
            scwin.vData1 = "E"; // Equal -> DB에 아무런것도 하지 않음

        } else {
            if ($c.stf.getObjectValue(edt_design_dd1_old) != "" &&
                $c.stf.getObjectValue(edt_design_dd1) == "" &&
                $c.stf.getObjectValue(edt_end_dd1) == "" &&
                $c.stf.getObjectValue(cmb_nsubmit_rsn1) == "") {
                scwin.vData1 = "D"; // delete

            } else {
                var vValStat = scwin.fn_chkValueExist(edt_design_dd1, edt_end_dd1, cmb_nsubmit_rsn1);
                if (vValStat == 9) {
                    $c.win.alert("한 건이상의 데이타를 입력하셔야 합니다.");
                    edt_design_dd1.focus();
                    return false;
                } else if (vValStat == 1 || vValStat == 4 || vValStat == 6) {
                    $c.win.alert("지정일1을  입력하셔야 합니다.");
                    edt_design_dd1.focus();
                    return false;
                } else if (vValStat == 3 || vValStat == 8) {
                    $c.win.alert("만료일1을  입력하셔야 합니다.");
                    edt_end_dd1.focus();
                    return false;
                } else if (vValStat == 5) {
                    $c.win.alert("사유1을  입력하셔야 합니다.");
                    cmb_nsubmit_rsn1.focus();
                    return false;
                } else if (vValStat == 0) {
                    scwin.vData1 = "U"; // update

                }
            }
        }

        // 두번째
        if ($c.stf.getObjectValue(edt_design_dd2_old) == $c.stf.getObjectValue(edt_design_dd2) &&
            $c.stf.getObjectValue(edt_end_dd2_old) == $c.stf.getObjectValue(edt_end_dd2) &&
            $c.stf.getObjectValue(txt_nsubmit_rsn2_old) == $c.stf.getObjectValue(cmb_nsubmit_rsn2)) {
            scwin.vData2 = "E"; // Equal -> DB에 아무런것도 하지 않음

        } else {
            if ($c.stf.getObjectValue(edt_design_dd2_old) != "" &&
                $c.stf.getObjectValue(edt_design_dd2) == "" &&
                $c.stf.getObjectValue(edt_end_dd2) == "" &&
                $c.stf.getObjectValue(cmb_nsubmit_rsn2) == "") {
                scwin.vData2 = "D"; // delete

            } else {
                var vValStat = scwin.fn_chkValueExist(edt_design_dd2, edt_end_dd2, cmb_nsubmit_rsn2);
                if (vValStat == 9) {
                    $c.win.alert("한 건이상의 데이타를 입력하셔야 합니다.");
                    edt_design_dd2.focus();
                    return false;
                } else if (vValStat == 1 || vValStat == 4 || vValStat == 6) {
                    $c.win.alert("지정일2를  입력하셔야 합니다.");
                    edt_design_dd2.focus();
                    return false;
                } else if (vValStat == 3 || vValStat == 8) {
                    $c.win.alert("만료일2를  입력하셔야 합니다.");
                    edt_end_dd2.focus();
                    return false;
                } else if (vValStat == 5) {
                    $c.win.alert("사유2를  입력하셔야 합니다.");
                    cmb_nsubmit_rsn2.focus();
                    return false;
                } else if (vValStat == 0) {
                    scwin.vData2 = "U"; // update

                }
            }
        }

        // 세번째
        if ($c.stf.getObjectValue(edt_design_dd3_old) == $c.stf.getObjectValue(edt_design_dd3) &&
            $c.stf.getObjectValue(edt_end_dd3_old) == $c.stf.getObjectValue(edt_end_dd3) &&
            $c.stf.getObjectValue(txt_nsubmit_rsn3_old) == $c.stf.getObjectValue(cmb_nsubmit_rsn3)) {
            scwin.vData3 = "E"; // Equal -> DB에 아무런것도 하지 않음

        } else {
            if ($c.stf.getObjectValue(edt_design_dd3_old) != "" &&
                $c.stf.getObjectValue(edt_design_dd3) == "" &&
                $c.stf.getObjectValue(edt_end_dd3) == "" &&
                $c.stf.getObjectValue(cmb_nsubmit_rsn3) == "") {
                scwin.vData3 = "D"; // delete

            } else {
                var vValStat = scwin.fn_chkValueExist(edt_design_dd3, edt_end_dd3, cmb_nsubmit_rsn3);
                if (vValStat == 9) {
                    $c.win.alert("한 건이상의 데이타를 입력하셔야 합니다.");
                    edt_design_dd3.focus();
                    return false;
                } else if (vValStat == 1 || vValStat == 4 || vValStat == 6) {
                    $c.win.alert("지정일3을  입력하셔야 합니다.");
                    edt_design_dd3.focus();
                    return false;
                } else if (vValStat == 3 || vValStat == 8) {
                    $c.win.alert("만료일3을  입력하셔야 합니다.");
                    edt_end_dd3.focus();
                    return false;
                } else if (vValStat == 5) {
                    $c.win.alert("사유3을  입력하셔야 합니다.");
                    cmb_nsubmit_rsn3.focus();
                    return false;
                } else if (vValStat == 0) {
                    scwin.vData3 = "U"; // update

                }
            }
        }
    }
    return true;
};


// 미제출정보 등록 & 수정 & 삭제	
scwin.fn_Insert = function() {
    if (scwin.fn_CheckValue() == false) {
        return;
    }

    //alert(	 vData1 +", "+  vData2 +", "+ vData3 );


    dts_Nsubmit_Input.insertRow();
    dts_Nsubmit_Input.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_isurcd));
    dts_Nsubmit_Input.setCellData(1, "DESIGN_DD1", $c.stf.getObjectValue(edt_design_dd1));
    dts_Nsubmit_Input.setCellData(1, "END_DD1", $c.stf.getObjectValue(edt_end_dd1));
    dts_Nsubmit_Input.setCellData(1, "NSUBMIT_RSN_CD1", $c.stf.getObjectValue(cmb_nsubmit_rsn1));
    dts_Nsubmit_Input.setCellData(1, "PROC_TYPE1", scwin.vData1);
    dts_Nsubmit_Input.setCellData(1, "DESIGN_DD2", $c.stf.getObjectValue(edt_design_dd2));
    dts_Nsubmit_Input.setCellData(1, "END_DD2", $c.stf.getObjectValue(edt_end_dd2));
    dts_Nsubmit_Input.setCellData(1, "NSUBMIT_RSN_CD2", $c.stf.getObjectValue(cmb_nsubmit_rsn2));
    dts_Nsubmit_Input.setCellData(1, "PROC_TYPE2", scwin.vData2);
    dts_Nsubmit_Input.setCellData(1, "DESIGN_DD3", $c.stf.getObjectValue(edt_design_dd3));
    dts_Nsubmit_Input.setCellData(1, "END_DD3", $c.stf.getObjectValue(edt_end_dd3));
    dts_Nsubmit_Input.setCellData(1, "NSUBMIT_RSN_CD3", $c.stf.getObjectValue(cmb_nsubmit_rsn3));
    dts_Nsubmit_Input.setCellData(1, "PROC_TYPE3", scwin.vData3);
    dts_Nsubmit_Input.setCellData(1, "EMP_NO", scwin.gEmpNo);
    if (scwin.vData1 == "U") {
        dts_Nsubmit_Input.setCellData(1, "DESIGN_DD1_OLD", $c.stf.getObjectValue(edt_design_dd1_old));
        dts_Nsubmit_Input.setCellData(1, "END_DD1_OLD", $c.stf.getObjectValue(edt_end_dd1_old));
        dts_Nsubmit_Input.setCellData(1, "NSUBMIT_RSN_CD1_OLD", $c.stf.getObjectValue(txt_nsubmit_rsn1_old));
    }
    if (scwin.vData2 == "U") {
        dts_Nsubmit_Input.setCellData(1, "DESIGN_DD2_OLD", $c.stf.getObjectValue(edt_design_dd2_old));
        dts_Nsubmit_Input.setCellData(1, "END_DD2_OLD", $c.stf.getObjectValue(edt_end_dd2_old));
        dts_Nsubmit_Input.setCellData(1, "NSUBMIT_RSN_CD2_OLD", $c.stf.getObjectValue(txt_nsubmit_rsn2_old));
    }
    if (scwin.vData3 == "U") {
        dts_Nsubmit_Input.setCellData(1, "DESIGN_DD3_OLD", $c.stf.getObjectValue(edt_design_dd3_old));
        dts_Nsubmit_Input.setCellData(1, "END_DD3_OLD", $c.stf.getObjectValue(edt_end_dd3_old));
        dts_Nsubmit_Input.setCellData(1, "NSUBMIT_RSN_CD3_OLD", $c.stf.getObjectValue(txt_nsubmit_rsn3_old));
    }

    //alert(dts_Nsubmit_Input.text);		
    var vAnswer = confirm('저장처리 하시겠습니까?');
    if (vAnswer == true) {
        trs_Nsubmit_Input.Action = "/SubmitStatus.do?method=processNSubmitInfo&inputMessageId=NSUBMIT_INFO_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Nsubmit_Input.KeyName = "toinb_dataid4";
        trs_Nsubmit_Input.KeyValue = "JSP(I:pInput=dts_Nsubmit_Input)";
        trs_Nsubmit_Input.Post();
    }
};
scwin.fn_Delete = function() {
    var vIsurCd = $c.stf.getObjectValue(txb_isurcd);
    if (vIsurCd == "") {
        $c.win.alert("회사코드로  내역조회후에 삭제처리가 가능합니다.");
        txb_ISUR_CD.focus();
        return false;
    }
    dts_Nsubmit_Delete.insertRow();
    dts_Nsubmit_Delete.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_isurcd));

    //alert(dts_Nsubmit_Input.text);		
    var vAnswer = confirm('전체 정보를 삭제처리 하시겠습니까?');
    if (vAnswer == true) {
        trs_Nsubmit_Delete.Action = "/SubmitStatus.do?method=removeNSubmitInfo&inputMessageId=NSUBMIT_INFO_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Nsubmit_Delete.KeyName = "toinb_dataid4";
        trs_Nsubmit_Delete.KeyValue = "JSP(I:pInput=dts_Nsubmit_Delete)";
        trs_Nsubmit_Delete.Post();
    }
};
scwin.dts_nsubmit_info_OnLoadError = function() {
    $c.stf.alert_error(dts_pnltsat_info);
};
scwin.img_search_onclick = function() {
    fn_Search();
};
scwin.img_design_dd1_onclick = function() {
    popUpCalendar2(edt_design_dd1);
};
scwin.img_design_dd2_onclick = function() {
    popUpCalendar2(edt_design_dd2);
};
scwin.img_design_dd3_onclick = function() {
    popUpCalendar2(edt_design_dd3);
};
scwin.img_end_dd1_onclick = function() {
    popUpCalendar2(edt_end_dd1);
};
scwin.img_end_dd2_onclick = function() {
    popUpCalendar2(edt_end_dd2);
};
scwin.img_end_dd3_onclick = function() {
    popUpCalendar2(edt_end_dd3);
};
scwin.img_insert_onclick = function() {
    scwin.fn_Insert();
};
scwin.img_delete_onclick = function() {
    scwin.fn_Delete();
};
scwin.img_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_nsubmit_info_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(edt_design_dd1_old, dts_nsubmit_info.getCellData(1, "DESIGN_DD1"));
    $c.stf.setObjectValue(edt_design_dd2_old, dts_nsubmit_info.getCellData(1, "DESIGN_DD2"));
    $c.stf.setObjectValue(edt_design_dd3_old, dts_nsubmit_info.getCellData(1, "DESIGN_DD3"));
    $c.stf.setObjectValue(edt_end_dd1_old, dts_nsubmit_info.getCellData(1, "END_DD1"));
    $c.stf.setObjectValue(edt_end_dd2_old, dts_nsubmit_info.getCellData(1, "END_DD2"));
    $c.stf.setObjectValue(edt_end_dd3_old, dts_nsubmit_info.getCellData(1, "END_DD3"));
    $c.stf.setObjectValue(txt_nsubmit_rsn1_old, dts_nsubmit_info.getCellData(1, "NSUBMIT_RSN_CD1"));
    $c.stf.setObjectValue(txt_nsubmit_rsn2_old, dts_nsubmit_info.getCellData(1, "NSUBMIT_RSN_CD2"));
    $c.stf.setObjectValue(txt_nsubmit_rsn3_old, dts_nsubmit_info.getCellData(1, "NSUBMIT_RSN_CD3"));
    if (dts_nsubmit_info.getCellData(1, "DESIGN_DD1") != '') {
        scwin.gProcType = 'M'; // 조회 후 1건 이상일때

    }
};
scwin.trs_Nsubmit_Input_OnFail = function() {
    $c.win.alert('trs_Nsubmit_Input.OnFail() :' + trs_Nsubmit_Input.ErrorMsg);
};
scwin.trs_Nsubmit_Input_OnSuccess = async function() {
    $c.win.alert("성공적으로 저장처리 되었습니다.");

    // 부모창 reload 처리해야함	
    $c.frame.path("../").fn_Search();
    await $c.frame.CloseFrame();
};
scwin.trs_Nsubmit_Delete_OnFail = function() {
    $c.win.alert('trs_Nsubmit_Delete.OnFail() :' + trs_Nsubmit_Delete.ErrorMsg);
};
scwin.trs_Nsubmit_Delete_OnSuccess = async function() {
    $c.win.alert("성공적으로 삭제처리 되었습니다.");

    // 부모창 reload 처리해야함	
    $c.frame.path("../").fn_Search();
    await $c.frame.CloseFrame();
};
scwin.btn_ISUR_CD_onclick = function() {
    if (gBondYn == 'Y') {
        $c.cm.IsurcdSearchBond(txb_ISUR_CD, txb_COM_NM);
    } else {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    }
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.btn_ISUR_CD_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM); // 법인명 검색 팝업

};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.gform_onload = function() {
    $c.stf.showObj(panel_hidden, false); // 히든처리!

    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    scwin.fn_SetCode();
    scwin.fn_GetParentValue();

    // 가우스헤더 셋팅
    dts_Nsubmit_Input.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=NSUBMIT_INFO_INOUT";
    dts_Nsubmit_Input.reset();
    dts_Nsubmit_Delete.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=NSUBMIT_INFO_INOUT";
    dts_Nsubmit_Delete.reset();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    //fn_InitSearch();

};
